def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and
               r not in (0, h - 1) and c not in (0, w - 1)]
    if not markers:
        return [row[:] for row in grid]

    mr, mc, color = markers[0]
    out = [row[:] for row in grid]

    def runs(vals):
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i
            while j + 1 < len(vals) and vals[j + 1] == vals[i]:
                j += 1
            yield i, j
            i = j + 1

    # Runs on top/bottom edges cast vertical rays; side-edge runs cast
    # horizontal rays. The ray color is the interior object's color.
    for a, b in runs(grid[0]):
        c = min(range(a, b + 1), key=lambda x: abs(x - mc))
        for r in range(1, h):
            if (r, c) in [(y, x) for y, x, _ in markers]:
                out[r][c] = 4
                break
            out[r][c] = color

    for a, b in runs(grid[h - 1]):
        c = min(range(a, b + 1), key=lambda x: abs(x - mc))
        for r in range(h - 2, -1, -1):
            if (r, c) in [(y, x) for y, x, _ in markers]:
                out[r][c] = 4
                break
            out[r][c] = color

    for a, b in runs([grid[r][0] for r in range(h)]):
        r = min(range(a, b + 1), key=lambda y: abs(y - mr))
        for c in range(1, w):
            if (r, c) in [(y, x) for y, x, _ in markers]:
                out[r][c] = 4
                break
            out[r][c] = color

    for a, b in runs([grid[r][w - 1] for r in range(h)]):
        r = min(range(a, b + 1), key=lambda y: abs(y - mr))
        for c in range(w - 2, -1, -1):
            if (r, c) in [(y, x) for y, x, _ in markers]:
                out[r][c] = 4
                break
            out[r][c] = color

    for r, c, _ in markers:
        out[r][c] = 4
    return out
